```python
from collections import OrderedDict


class LRUCache:
    """Least Recently Used cache with O(1) get and put operations."""

    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = OrderedDict()
        self.hits = 0
        self.misses = 0

    def get(self, key):
        """Return value if key exists, else None. Mark accessed keys as recently used."""
        if key not in self.cache:
            self.misses += 1
            return None
        self.hits += 1
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        """Add or update key-value pair. Evict least recently used item if over capacity."""
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

    def stats(self):
        """Return cache statistics: hits, misses, and current size."""
        return {
            'hits': self.hits,
            'misses': self.misses,
            'size': len(self.cache)
        }
